{"path": "poker.py", "content": "from collections import Counter

RANKS = {r: i for i, r in enumerate("23456789TJQKA", start=2)}


def _card_value(card):
    rank = card[:-1]
    if rank == "10":
        rank = "T"
    return RANKS[rank], card[-1]


def _score(hand):
    cards = [_card_value(c) for c in hand.split()]
    values = sorted((v for v, _ in cards), reverse=True)
    suits = {s for _, s in cards}

    counts = Counter(values)
    # Group by (count, value) descending, e.g. full house -> [(3, x), (2, y)]
    groups = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    ordered = [v for v, _ in groups]
    shape = [c for _, c in groups]

    flush = len(suits) == 1
    straight = len(counts) == 5 and values[0] - values[4] == 4
    if values == [14, 5, 4, 3, 2]:
        straight = True
        ordered = [5, 4, 3, 2, 1]

    if straight and flush:
        category = 8
    elif shape == [4, 1]:
        category = 7
    elif shape == [3, 2]:
        category = 6
    elif flush:
        category = 5
    elif straight:
        category = 4
    elif shape == [3, 1, 1]:
        category = 3
    elif shape == [2, 2, 1]:
        category = 2
    elif shape == [2, 1, 1, 1]:
        category = 1
    else:
        category = 0
    return category, ordered


def best_hands(hands):
    scores = [_score(h) for h in hands]
    best = max(scores)
    return [h for h, s in zip(hands, scores) if s == best]
